      "id": "BP-A16",
      "name": "ML Training Pipeline",
      "category": "AI / ML",
      "status": "Implemented",
      "wave": "C",
      "summary": "SageMaker Pipelines with training jobs and hyperparameter tuning, running in a VPC with KMS-encrypted S3 training data and model artifacts plus a SageMaker endpoint.",
      "file": "blueprints/ai/ml-training-pipeline.yaml",
      "components": [
        "aws-vpc",
        "aws-subnet",
        "aws-security-group",
        "aws-kms",
        "aws-s3",
        "aws-s3",
        "aws-sagemaker-pipeline",
        "aws-sagemaker-endpoint"
      ],
      "componentCount": 8,
      "policyPack": null,
      "manifest": "# Blueprint BP-A16: ML Training Pipeline\n# Architecture: VPC + Subnet + SG + KMS + S3 (training data/model artifacts) + SageMaker Pipeline + SageMaker Endpoint\n# Platform-only blueprint — pipeline reads training data and writes model artifacts\n\nservice: ml-training-pipeline\ndescription: ML training pipeline with SageMaker Pipeline for model training and deployment\n\ncomponents:\n  - id: ml-vpc\n    type: platform\n    platform: aws-vpc\n    config:\n      cidrBlock: '10.0.0.0/16'\n\n  - id: ml-subnet\n    type: platform\n    platform: aws-subnet\n    config:\n      vpcId: 'platform:ml-vpc'\n      cidrBlock: '10.0.1.0/24'\n      availabilityZone: us-east-1a\n      mapPublicIpOnLaunch: false\n\n  - id: ml-sg\n    type: platform\n    platform: aws-security-group\n    config:\n      vpcId: 'platform:ml-vpc'\n      description: ML training security group\n\n  - id: encryption-key\n    type: platform\n    platform: aws-kms\n    config:\n      description: ML pipeline encryption key\n      enableKeyRotation: true\n\n  - id: training-data\n    type: platform\n    platform: aws-s3\n    config:\n      versioning: true\n\n  - id: model-artifacts\n    type: platform\n    platform: aws-s3\n    config:\n      versioning: true\n\n  - id: training-pipeline\n    type: platform\n    platform: aws-sagemaker-pipeline\n    config:\n      pipelineDefinition: '{\"Version\": \"2020-12-01\", \"Steps\": []}'\n      pipelineDescription: Training pipeline for model v1\n      parallelismConfiguration:\n        maxParallelExecutionSteps: 3\n\n  - id: model-endpoint\n    type: platform\n    platform: aws-sagemaker-endpoint\n    config:\n      instanceType: ml.m5.large\n      initialInstanceCount: 1\n      vpcConfig:\n        subnetIds:\n          - 'platform:ml-subnet'\n        securityGroupIds:\n          - 'platform:ml-sg'\n\nbindings:\n  - type: bindsTo\n    source: training-pipeline\n    target: training-data\n    config:\n      resourceType: bucket\n      accessLevel: read\n\n  - type: bindsTo\n    source: training-pipeline\n    target: model-artifacts\n    config:\n      resourceType: bucket\n      accessLevel: write\n\npolicyPack: Baseline\n"
