      "componentCount": 9,
      "policyPack": null,
      "manifest": "# Blueprint BP-I10: MSK Kafka\n# Architecture: VPC + 3 Subnets + SG + KMS + MSK Configuration + MSK Cluster + S3 (logs)\n# Platform-only blueprint — 1 edge for log delivery\n\nservice: msk-kafka\ndescription: Amazon MSK Kafka cluster with multi-AZ deployment and TLS encryption\n\ncomponents:\n  - id: msk-vpc\n    type: platform\n    platform: aws-vpc\n    config:\n      cidrBlock: '10.0.0.0/16'\n\n  - id: msk-subnet-1\n    type: platform\n    platform: aws-subnet\n    config:\n      vpcId: 'platform:msk-vpc'\n      cidrBlock: '10.0.1.0/24'\n      availabilityZone: us-east-1a\n      mapPublicIpOnLaunch: false\n\n  - id: msk-subnet-2\n    type: platform\n    platform: aws-subnet\n    config:\n      vpcId: 'platform:msk-vpc'\n      cidrBlock: '10.0.2.0/24'\n      availabilityZone: us-east-1b\n      mapPublicIpOnLaunch: false\n\n  - id: msk-subnet-3\n    type: platform\n    platform: aws-subnet\n    config:\n      vpcId: 'platform:msk-vpc'\n      cidrBlock: '10.0.3.0/24'\n      availabilityZone: us-east-1c\n      mapPublicIpOnLaunch: false\n\n  - id: msk-sg\n    type: platform\n    platform: aws-security-group\n    config:\n      vpcId: 'platform:msk-vpc'\n      description: MSK cluster security group\n\n  - id: msk-key\n    type: platform\n    platform: aws-kms\n    config:\n      description: MSK encryption key\n      enableKeyRotation: true\n\n  - id: msk-config\n    type: platform\n    platform: aws-msk-configuration\n    config:\n      kafkaVersions:\n        - '3.5.1'\n      serverProperties: |\n        auto.create.topics.enable=false\n        log.retention.hours=168\n        default.replication.factor=3\n        min.insync.replicas=2\n\n  - id: msk-cluster\n    type: platform\n    platform: aws-msk-cluster\n    config:\n      kafkaVersion: '3.5.1'\n      numberOfBrokerNodes: 3\n      instanceType: kafka.m5.large\n      ebsVolumeSize: 100\n      encryptionInTransit: TLS\n      enhancedMonitoring: PER_TOPIC_PER_BROKER\n      clientAuthentication:\n        sasl:\n          iam: true\n      subnetIds:\n        - 'platform:msk-subnet-1'\n        - 'platform:msk-subnet-2'\n        - 'platform:msk-subnet-3'\n      securityGroupIds:\n        - 'platform:msk-sg'\n\n  - id: msk-logs\n    type: platform\n    platform: aws-s3\n    config:\n      versioning: true\n\nbindings:\n  - type: bindsTo\n    source: msk-cluster\n    target: msk-logs\n    config:\n      resourceType: bucket\n      accessLevel: write\n\npolicyPack: Baseline\n"
